1717	// Software prefetch of upcoming weight blocks. The gemv/gemm inner loop streams
1718	// block_q1_0x64 sequentially (1152 B = 18 cache lines each); the HW prefetcher
1719	// on this core is shallow (L3C_PFP_LINE_NUM=0, D$ 4 entries), so it cannot run
1720	// far enough ahead to hide the L3/DRAM miss latency that makes the kernel
1721	// load-bound. Pull the block Q1_PREFETCH_DIST ahead into cache explicitly.
1722	// Pure hint: results are unchanged. Needs -march=..._zicbop (else
1723	// __builtin_prefetch is a nop); Q1_PREFETCH_DIST=0 disables it entirely.
1724	// Default 1 (measured best on ax46mpv_fpga_l3: 2.14M -> 1.39M cyc on the K=51
1725	// V-proj node, 1.54x; distances 2/4 were worse - one 18-line block ahead
1726	// already hides the L3/DRAM latency, further lookahead only adds cache/MSHR
1727	// pressure). Other cores can override at build time.
1728	//
1729	// always_inline is load-bearing, not a hint: a prefetch has no observable side
1730	// effect, so whenever the compiler leaves this helper out of line ipa-pure-const
1731	// marks it pure and DCE then deletes every call - no warning, no prefetch left,
1732	// and results stay correct so no test notices. GCC 14.2 does exactly that at
1733	// -Os (CMake MinSizeRel), which cost the whole optimization there. Verify with
1734	// check-prefetch.sh in the repo root: it counts prefetch.r per entry point.
1735	#ifndef Q1_PREFETCH_DIST
1736	#define Q1_PREFETCH_DIST 1
1737	#endif
1738	static inline __attribute__((always_inline))
1739	void q1_prefetch_block(const block_q1_0x64 * bx, int l, int nb) {
1740	#if Q1_PREFETCH_DIST > 0
1741	    const int t = l + Q1_PREFETCH_DIST;
1742	    if (t < nb) {
1743	        const char * p = (const char *) &bx[t];
1744	        for (size_t o = 0; o < sizeof(block_q1_0x64); o += 64) {
1745	            __builtin_prefetch(p + o, 0, 3);
1746	        }
1747	    }
1748	#else
1749	    (void) bx; (void) l; (void) nb;
1750	#endif
1751	}
