// ---- Q1_0 row-parallel 64x1 (F4d) -----------------------------------------
// lane j = row j; per column ONE vlm mask load + vsub.vx/vadd.vx,mu = net
// +-y. Zero reductions. zve32f only: fp16 scales are expanded with integer
// bit math (no zvfh), int16 group sums are widened with vsext+vfcvt (no
// vfwcvt.f.x.v - some RTLs reject it). LMUL adapts to VLEN so the 64 fp32
// accumulator lanes exactly fill the machine:
//   VLEN=512 : i16 m2 / f32 m4      VLEN>=1024: i16 m1 / f32 m2

#if defined(__riscv_v_intrinsic)

// Software prefetch of upcoming weight blocks. The gemv/gemm inner loop streams
// block_q1_0x64 sequentially (1152 B = 18 cache lines each); the HW prefetcher
// on this core is shallow (L3C_PFP_LINE_NUM=0, D$ 4 entries), so it cannot run
// far enough ahead to hide the L3/DRAM miss latency that makes the kernel
// load-bound. Pull the block Q1_PREFETCH_DIST ahead into cache explicitly.
// Pure hint: results are unchanged. Needs -march=..._zicbop (else
// __builtin_prefetch is a nop); Q1_PREFETCH_DIST=0 disables it entirely.
// Default 1 (measured best on ax46mpv_fpga_l3: 2.14M -> 1.39M cyc on the K=51
// V-proj node, 1.54x; distances 2/4 were worse - one 18-line block ahead
// already hides the L3/DRAM latency, further lookahead only adds cache/MSHR
// pressure). Other cores can override at build time.
//
// always_inline is load-bearing, not a hint: a prefetch has no observable side
// effect, so whenever the compiler leaves this helper out of line ipa-pure-const
// marks it pure and DCE then deletes every call - no warning, no prefetch left,
// and results stay correct so no test notices. GCC 14.2 does exactly that at
// -Os (CMake MinSizeRel), which cost the whole optimization there. Verify with
// check-prefetch.sh in the repo root: it counts prefetch.r per entry point.
#ifndef Q1_PREFETCH_DIST
#define Q1_PREFETCH_DIST 1
#endif
static inline __attribute__((always_inline))
void q1_prefetch_block(const block_q1_0x64 * bx, int l, int nb) {
#if Q1_PREFETCH_DIST > 0
    const int t = l + Q1_PREFETCH_DIST;
    if (t < nb) {
        const char * p = (const char *) &bx[t];
        for (size_t o = 0; o < sizeof(block_q1_0x64); o += 64) {
            __builtin_prefetch(p + o, 0, 3);
        }
    }
#else
    (void) bx; (void) l; (void) nb;
#endif
}

// exact for normals/+-0; q1_0 scales never carry fp16 subnormals
static inline vfloat32m4_t q1_expand_fp16_64_m4(const ggml_half * p) {
