// ---- Q1_VD4DOT: the same row-parallel gemv on nds.vd4dots.vv (XAndesVDot) ------
// Needs the Q1_VD4DOT sign-plane order (repack.h q1_0x64_sign_bit) and
// -march=..._xandesvdot. Only the VLEN>=1024 shape is implemented: e32/m2 is
// then exactly 64 i32 lanes = 64 rows, and the same register group seen as i8
// is 256 bytes = 64 rows x 4 columns, which is the operand shape the
// instruction consumes. Everything else falls through to the generic kernel.
#if defined(Q1_VD4DOT) && Q1_VD4DOT

// vd[lane] += sum_{k<4} vs1[4*lane+k] * vs2[4*lane+k], int8 x int8 into i32.
// ---- Q1_VD4DOT gemm: 4 output rows per pass, weight stream read once for all 4 --
// Same dot and the same weight stream as the gemv above; only the activation
// side is new. The x4 activation block stores qs[c*4 + m] (blck_size_interleave
=== repack.h ===
// Bit position of row j's sign for column c inside block_q1_0x64::qs, as a flat
// bit index. The repack writer and every gemv/gemm reader go through here, so
// the two supported orders stay consistent by construction.
//
